-- case: MATCH p=allShortestPaths((s)-[*1..]->(e)) WHERE s.name IN ['left','overlap'] AND e.name IN ['overlap','right'] AND NOT(id(s)=id(e)) RETURN p
-- pgsql_params:{"__strlit0":"","__strlit1":"insert into traversal_terminal_filter (id) select distinct n1.id from node n1 where ((n1.properties -\u003e\u003e E'name') = any (array [E'overlap', E'right']::text[])) and n1.id is not null;","pi0":"insert into next_front (root_id, next_id, depth, satisfied, is_cycle, path) with s1_seed(root_id) as not materialized (select n0.id as root_id from node n0 where ((n0.properties -\u003e\u003e E'name') = any (array [E'left', E'overlap']::text[]))) select e0.start_id, e0.end_id, 1, exists (select 1 from traversal_terminal_filter where traversal_terminal_filter.id = e0.end_id), e0.start_id = e0.end_id, array [e0.id] from s1_seed join edge e0 on e0.start_id = s1_seed.root_id where dawgs_admit_traversal_v1(1, e0.id) and case when exists (select 1 from s1_seed where s1_seed.root_id = e0.start_id) then case when (select count(*)::int8 from traversal_terminal_filter where traversal_terminal_filter.id = e0.start_id) = 0 then true else shortest_path_self_endpoint_error(e0.start_id, e0.start_id) end else true end;","pi1":"insert into next_front (root_id, next_id, depth, satisfied, is_cycle, path) select s1.root_id, e0.end_id, s1.depth + 1, exists (select 1 from traversal_terminal_filter where traversal_terminal_filter.id = e0.end_id), false, s1.path || e0.id from forward_front s1 join edge e0 on e0.start_id = s1.next_id where dawgs_admit_traversal_v1(s1.depth + 1, e0.id) and e0.id != all (s1.path);"}
