-- case: MATCH p=allShortestPaths((s)-[*1..]->(e)) WHERE s.name IN ['left','overlap'] AND e.name IN ['overlap','right'] WITH p,s,e WHERE id(s)<>id(e) RETURN p
-- pgsql_params:{"__strlit0":"endpoint","__strlit1":"left","__strlit2":"overlap","__strlit3":"right","__strlit4":"pair"}
with s0 as (with s1 as (with asp_root_endpoints(root_id, admitted) as materialized (select n0.id as root_id, dawgs_admit_traversal_work_v2(1, 64, @__strlit0::text) as admitted from node n0 where ((n0.properties ->> E'name') = any (array [@__strlit1::text, @__strlit2::text]::text[]))), asp_terminal_endpoints(terminal_id, admitted) as materialized (select n1.id as terminal_id, dawgs_admit_traversal_work_v2(1, 64, @__strlit0::text) as admitted from node n1 where ((n1.properties ->> E'name') = any (array [@__strlit2::text, @__strlit3::text]::text[]))), asp_resolved_endpoints(root_id, terminal_id) as (select asp_root_endpoints.root_id, asp_terminal_endpoints.terminal_id from asp_root_endpoints, asp_terminal_endpoints where asp_root_endpoints.admitted and asp_terminal_endpoints.admitted and dawgs_admit_traversal_work_v2(1, 64, @__strlit4::text)), s2(root_id, next_id, depth, satisfied, is_cycle, path) as (select all_shortest_paths_dag_v2.* from asp_resolved_endpoints, all_shortest_paths_dag_v2(0, asp_resolved_endpoints.root_id, asp_resolved_endpoints.terminal_id, 1, 0, false, array []::int2[], false)) select (array [(n0.id, n0.kind_ids, n0.properties)::nodecomposite]::nodecomposite[] || coalesce(m0_hydrated.nodes, array []::nodecomposite[]), coalesce(m0_hydrated.edges, array []::edgecomposite[]))::pathcomposite as ep0, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n1.id, n1.kind_ids, n1.properties)::nodecomposite as n1 from s2 join node n0 on n0.id = s2.root_id join node n1 on n1.id = s2.next_id join lateral (select array_agg((m0_terminal.id, m0_terminal.kind_ids, m0_terminal.properties)::nodecomposite order by m0_path_index)::nodecomposite[] as nodes, array_agg((m0_edge.id, m0_edge.start_id, m0_edge.end_id, m0_edge.kind_id, m0_edge.properties)::edgecomposite order by m0_path_index)::edgecomposite[] as edges, count(*)::int8 as hydrated_count from generate_subscripts(s2.path, 1) as m0_path_index join edge m0_edge on m0_edge.id = (s2.path)[m0_path_index] join node m0_terminal on m0_terminal.id = m0_edge.end_id) m0_hydrated on true where m0_hydrated.hydrated_count = cardinality(s2.path)) select case when (s1.n0).id is null or s1.ep0 is null or (s1.n1).id is null then null else s1.ep0 end as pc0, s1.n0 as n0, s1.n1 as n1 from s1 where ((s1.n0).id <> (s1.n1).id)) select s0.pc0 as p from s0;
